import heapq

def min_operations_to_increasing(n, k, a, b):
    if k == 0:
        # If there are no fixed elements, simply check if the array is already increasing
        operations = 0
        last_valid = 0
        for i in range(n):
            if a[i] <= last_valid:
                operations += 1
                last_valid += 1
            else:
                last_valid = a[i]
        return operations

    # Convert b to a set for O(1) lookups
    fixed_positions = set(b)

    # Priority queue to store fixed elements with their indices
    fixed_elements = []
    for i in b:
        heapq.heappush(fixed_elements, (a[i-1], i-1))

    operations = 0
    last_valid = 0
    i = 0

    while i < n:
        if i in fixed_positions:
            # Process fixed element
            fixed_value, _ = heapq.heappop(fixed_elements)
            if fixed_value <= last_valid:
                return -1  # Impossible to make increasing
            last_valid = fixed_value
        else:
            # Process non-fixed element
            if a[i] <= last_valid:
                operations += 1
                last_valid += 1
            else:
                last_valid = a[i]
        i += 1

    # Check if there are any remaining fixed elements
    while fixed_elements:
        fixed_value, _ = heapq.heappop(fixed_elements)
        if fixed_value <= last_valid:
            return -1  # Impossible to make increasing
        last_valid = fixed_value

    return operations

